import React, { useState } from 'react';
import RepeatingCard from '../../components/RepeatingCard';
import PhotoUploadGrid from '../../components/PhotoUploadGrid';
import { ErrorAlert } from '../../components/EmptyState';
import { photoService, photoBriefImageService, extractApiError } from '../../api/services';

const PHOTO_BRIEF_CATEGORIES = [
  { value: 'MOODBOARD', label: 'Moodboard / shot references (9:16)', aspect: 'portrait', hint: 'Drag & drop portrait frames, or click to browse' },
  { value: 'WARDROBE', label: 'Wardrobe reference', aspect: 'square', hint: 'Drag & drop wardrobe references, or click to browse' },
  { value: 'BACKGROUND', label: 'Background reference', aspect: 'square', hint: 'Drag & drop background references, or click to browse' },
];

function AssignmentChips({ label, pool, selectedIds, onToggle, emptyHint }) {
  if (pool.length === 0) {
    return (
      <div className="rr-wizfield">
        <label>{label}</label>
        <div style={{ fontSize: 12, color: 'rgba(0,0,0,.45)' }}>{emptyHint}</div>
      </div>
    );
  }
  return (
    <div className="rr-wizfield">
      <label>
        {label} — {selectedIds.length ? pool.filter((p) => selectedIds.includes(p.id)).map((p) => p.name).join(', ') : 'none'}
      </label>
      <div className="rr-wiz-chips">
        {pool.map((item) => (
          <span className="rr-wiz-chip" key={item.id}>
            <label>
              <input type="checkbox" checked={selectedIds.includes(item.id)} onChange={() => onToggle(item.id)} />
              {item.name}
            </label>
          </span>
        ))}
      </div>
    </div>
  );
}

export default function StepPhotos({ plan, onChanged }) {
  const [error, setError] = useState('');
  const briefs = plan?.photos || [];
  const modelPool = plan?.plan_models || [];
  const locationPool = plan?.plan_locations || [];
  const propPool = plan?.props || [];

  const run = async (fn, message) => {
    try {
      await fn();
      onChanged();
    } catch (err) {
      setError(extractApiError(err, message));
    }
  };

  const add = () =>
    run(
      () => photoService.create({ shoot_plan: plan.id, title: `Shot ${briefs.length + 1}`, order: briefs.length }),
      'Could not add shot.'
    );
  const patch = (id, payload) => run(() => photoService.patch(id, payload), 'Could not save changes.');
  const remove = (id) => run(() => photoService.remove(id), 'Could not remove shot.');
  const move = (id, dir) => {
    const idx = briefs.findIndex((p) => p.id === id);
    const swapWith = briefs[idx + dir];
    if (!swapWith) return;
    run(
      () =>
        Promise.all([
          photoService.patch(id, { order: swapWith.order }),
          photoService.patch(swapWith.id, { order: briefs[idx].order }),
        ]),
      'Could not reorder.'
    );
  };
  const duplicate = (p) =>
    run(
      () =>
        photoService.create({
          shoot_plan: plan.id,
          title: `${p.title} (copy)`,
          description: p.description,
          quantity: p.quantity,
          notes_to_designer: p.notes_to_designer,
          shot_type: p.shot_type,
          order: briefs.length,
        }),
      'Could not duplicate.'
    );

  const toggleAssignment = (brief, field, id) => {
    const current = brief[field] || [];
    const next = current.includes(id) ? current.filter((x) => x !== id) : [...current, id];
    patch(brief.id, { [field]: next });
  };

  return (
    <>
      <div className="rr-wiz-step-title">Photos</div>
      <ErrorAlert message={error} />

      <div className="rr-stepbar">
        <span className="rr-stepbar__count">{briefs.length} shot(s) briefed</span>
        <button type="button" className="rr-toggle-btn rr-toggle-btn--active" onClick={add}>
          + Add Shot
        </button>
      </div>

      {briefs.length === 0 && (
        <div className="rr-wiz-empty">
          <div className="rr-wiz-empty__title">No shots briefed yet</div>
          <div className="rr-wiz-empty__text">List the still shots needed and any references.</div>
          <button type="button" className="rr-toggle-btn rr-toggle-btn--active" onClick={add}>
            + Add Shot
          </button>
        </div>
      )}

      {briefs.map((p, idx) => (
        <RepeatingCard
          key={p.id}
          title={`Shot ${idx + 1}${p.title ? ` — ${p.title}` : ''}`}
          complete={!!p.description}
          summary={p.description || p.title || 'Untitled'}
          isFirst={idx === 0}
          isLast={idx === briefs.length - 1}
          onMoveUp={() => move(p.id, -1)}
          onMoveDown={() => move(p.id, 1)}
          onDuplicate={() => duplicate(p)}
          onRemove={() => remove(p.id)}
        >
          <div className="rr-wizfield">
            <label>
              Shot description <span className="rr-wiz-required">*</span>
            </label>
            <textarea
              rows={2}
              defaultValue={p.description}
              onBlur={(e) => patch(p.id, { description: e.target.value })}
              placeholder="e.g. Wide hero shot of villa exterior at golden hour"
            />
          </div>
          <div className="rr-wizgrid-2">
            <div className="rr-wizfield">
              <label>Number of photos</label>
              <input type="number" min={1} defaultValue={p.quantity} onBlur={(e) => patch(p.id, { quantity: e.target.value })} />
            </div>
            <div className="rr-wizfield">
              <label>Shot type</label>
              <select defaultValue={p.shot_type} onBlur={(e) => patch(p.id, { shot_type: e.target.value })}>
                {['PORTRAIT', 'PRODUCT', 'LIFESTYLE', 'CANDID', 'GROUP', 'BTS', 'OTHER'].map((v) => (
                  <option key={v} value={v}>
                    {v}
                  </option>
                ))}
              </select>
            </div>
          </div>
          <div className="rr-wizfield">
            <label>Notes to designer</label>
            <textarea rows={2} defaultValue={p.notes_to_designer} onBlur={(e) => patch(p.id, { notes_to_designer: e.target.value })} placeholder="Styling, angle, props in frame…" />
          </div>

          {PHOTO_BRIEF_CATEGORIES.map((cat) => (
            <PhotoUploadGrid
              key={cat.value}
              label={cat.label}
              aspect={cat.aspect}
              hint={cat.hint}
              photos={(p.photos || []).filter((ph) => ph.category === cat.value)}
              onUpload={(file) => run(() => photoBriefImageService.upload(p.id, file, { category: cat.value }), 'Upload failed.')}
              onRemove={(photoId) => run(() => photoBriefImageService.remove(photoId), 'Could not remove photo.')}
            />
          ))}

          <div style={{ borderTop: '1px solid rgba(0,0,0,.08)', paddingTop: 14, marginTop: 4 }}>
            <AssignmentChips
              label="Models"
              pool={modelPool}
              selectedIds={p.assigned_models || []}
              onToggle={(id) => toggleAssignment(p, 'assigned_models', id)}
              emptyHint="Add models in the People & Models step first."
            />
            <AssignmentChips
              label="Locations"
              pool={locationPool}
              selectedIds={p.assigned_locations || []}
              onToggle={(id) => toggleAssignment(p, 'assigned_locations', id)}
              emptyHint="Add locations in the Locations step first."
            />
            <AssignmentChips
              label="Props"
              pool={propPool}
              selectedIds={p.assigned_props || []}
              onToggle={(id) => toggleAssignment(p, 'assigned_props', id)}
              emptyHint="Add props in the Props step first."
            />
          </div>
        </RepeatingCard>
      ))}
    </>
  );
}
